mapper.select:
SELECT request_count
FROM ai_search_usage
WHERE member_id = #{memberId}
  AND usage_date = #{date}
FOR UPDATE

mapper.update:
UPDATE ai_search_usage
SET request_count = request_count + 1,
    updated_at = #{now}
WHERE member_id = #{memberId}
  AND usage_date = #{date}

UPDATE ai_search_usage
SET input_tokens = input_tokens + #{inputTokens},
    output_tokens = output_tokens + #{outputTokens},
    updated_at = #{now}
WHERE member_id = #{memberId}
  AND usage_date = #{date}

mapper.delete:
DELETE FROM ai_search_usage
WHERE usage_date < #{cutoff}
LIMIT #{limit}
